def _lookup(keys, values, temperature):
    """查表：优先取恰好落在 0.01 K 网格上的值，否则取最近的网格点。"""
    i = bisect.bisect_left(keys, float(temperature))
    if i < len(keys) and abs(keys[i] - temperature) < 1e-9:
        return float(values[i])
    cands = [j for j in (i - 1, i, i + 1) if 0 <= j < len(keys)]
    best = min(cands, key=lambda j: abs(keys[j] - float(temperature)))
    return float(values[best])


def water_density(temperature):
    """温度(K) -> 水的密度 (g/mL)。"""
    return _lookup(_DENSITY_K, _DENSITY_V, temperature)


def water_capacity(temperature):
    """温度(K) -> 水的比热容 (J/(g*K))。"""
    return _lookup(_CAPACITY_K, _CAPACITY_V, temperature)
